      add('fowi_idf', 'repressiv', '§ 46 Abs. 1 OWiG i. V. m. § 163b StPO', [nurPol(), mk('Verdacht einer Ordnungswidrigkeit', 'ja'), mk('Identität sonst nicht oder nur unter erheblichen Schwierigkeiten feststellbar', tri('idSchwer')), mk('Festhalten steht nicht außer Verhältnis zur Bedeutung der Ordnungswidrigkeit', tri('idVerh'))].filter(Boolean), 'Festhalten zur Identitätsfeststellung (deutlich kürzer als 12 Stunden)', VERF.idf);
