    if (A.has('platzverweis')) durchs('f35_3nr', 'pv', '§ 35 Abs. 1 Nr. 3 PolG NRW', 'Rechtmäßiger Platzverweis bzw. Aufenthaltsverbot (§ 34)', 'Durchsetzungsgewahrsam bis zur Erreichung des Zwecks');
    if (A.has('wohnung')) durchs('f35_4nr', 'wv', '§ 35 Abs. 1 Nr. 4 PolG NRW', 'Rechtmäßige Wohnungsverweisung bzw. Rückkehrverbot (§ 34a)', 'Durchsetzungsgewahrsam');
