  /** Gesamturteil, Hinweise und Vermerk aus den Einzelprüfungen. */
  function summary(F) {
    const s = fe.st, g = F.filter(f => f.status === 'greift'), o = F.filter(f => f.status === 'offen');
    const hints = [];
    if (s.feArt === 'beschraenkung') hints.push('Nur Freiheitsbeschränkung (kurzes Anhalten): Art. 104 Abs. 2 GG mit Richtervorbehalt greift nicht – die Rechtsgrundlage für das Anhalten ist trotzdem nötig.');
    if (g.some(f => f.zweck === 'repressiv') && g.some(f => f.zweck === 'praeventiv')) hints.push('Gemengelage: repressive und präventive Grundlage tragen nebeneinander – Zweck dokumentieren; er bestimmt das Verfahren (StPO: Staatsanwaltschaft und § 128; PolG: § 36, Amtsgericht nach FamFG).');
    if (s.anlass.includes('minderj') && s.anlass.includes('straftat')) hints.push('Jugendliche: Erziehungsberechtigte benachrichtigen; U-Haft nur, wenn nicht durch vorläufige Anordnungen über die Erziehung ersetzbar (§ 72 JGG).');
    if (g.length) hints.push('Verhältnismäßigkeit: Freiheitsentziehung nur als letztes Mittel und nur so lange wie nötig; mildere Mittel (Platzverweis, Ansprache, Übergabe an Angehörige) dokumentieren.');
    const level = !s.anlass.length ? 'leer' : g.length ? 'greift' : o.length ? 'offen' : 'keine';
    return { g, o, hints, level };
  }
  function vermerk(F, sum) {
    const s = fe.st, d = new Date(), L = [];
    L.push(`Prüfung Freiheitsentziehung – ${pad(d.getDate())}.${pad(d.getMonth() + 1)}.${d.getFullYear()} ${pad(d.getHours())}:${pad(d.getMinutes())} Uhr`);
    L.push(`Anlass: ${s.anlass.map(a => ANLASS_L[a]).join('; ') || '[Anlass]'}`);
    L.push(`Handelnde: ${s.akteur === 'polizei' ? 'Polizei' : 'Privatperson (Jedermann)'}`);
    if (sum.g.length) {
      L.push('', 'Rechtsgrundlage(n):');
      for (const f of sum.g) {
        L.push(`– ${f.norm}: ${f.title.replace(/ – .*$/, '')}`);
        for (const t of f.tb) L.push(`   + ${t.m}${t.s ? ' (' + t.s + ')' : ''}`);
        L.push(`   Rechtsfolge: ${f.folge}`);
      }
    } else L.push('', 'Keine Rechtsgrundlage abschließend erfüllt.');
    if (sum.o.length) { L.push('', 'Noch zu klären:'); for (const f of sum.o) L.push(`– ${f.norm}: ${f.tb.filter(t => t.v === 'offen').map(t => t.m).join('; ')}`); }
    const verf = [...new Set(sum.g.flatMap(f => f.verf))];
    if (verf.length) { L.push('', 'Verfahren:'); for (const v of verf) L.push(`– ${v}`); }
    if (sum.hints.length) { L.push('', 'Hinweise:'); for (const h of sum.hints) L.push(`– ${h}`); }
    L.push('', 'Orientierungshilfe, keine Rechtsberatung. Landesrecht NRW sinngemäß – Wortlaut prüfen.');
    return L.join('\n');
  }

