  const iBtn = (key, label) => (key && (TIPS[key] || LAW[key]) ? `<button type="button" class="wf-i" data-fei="${key}" aria-label="Erläuterung: ${esc(label || '')}"><span aria-hidden="true">i</span></button>` : '');
